import fs from "node:fs/promises";
import path from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

// Matches the deterministic extension ID generated by our fixed manifest key
export const EXTENSION_ID = "iaegfhibolfagbcpbpekolcafcihkhfp";
export const HOST_NAME = "com.coderelay.host";

export async function registerNativeHost(cliDir: string): Promise<{ success: boolean; manifestPath: string }> {
    const hostExePath = path.resolve(cliDir, "host.exe");
    const hostBatPath = path.resolve(cliDir, "host.bat");
    const hostShPath = path.resolve(cliDir, "host.sh");

    let executablePath = hostBatPath;
    if (process.platform === "win32") {
        try {
            await fs.access(hostExePath);
            executablePath = hostExePath;
        } catch {
            executablePath = hostBatPath;
        }
    } else {
        executablePath = hostShPath;
    }

    const manifestPath = path.resolve(cliDir, `${HOST_NAME}.json`);

    const manifestContent = {
        name: HOST_NAME,
        description: "CodeRelay Native Messaging Host",
        path: executablePath,
        type: "stdio",
        allowed_origins: [
            `chrome-extension://${EXTENSION_ID}/`
        ]
    };

    // 1. Write the manifest JSON
    await fs.writeFile(manifestPath, JSON.stringify(manifestContent, null, 2), "utf-8");

    // 2. Register in Windows Registry for all Chromium browsers (Chrome, Brave, Edge, Chromium, Vivaldi)
    if (process.platform === "win32") {
        const browserKeys = [
            `HKCU\\Software\\Google\\Chrome\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\BraveSoftware\\Brave-Browser\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\BraveSoftware\\Brave-Browser-Beta\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\BraveSoftware\\Brave-Browser-Nightly\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\Microsoft\\Edge\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\Chromium\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\Vivaldi\\NativeMessagingHosts\\${HOST_NAME}`
        ];

        for (const regKey of browserKeys) {
            try {
                await execFileAsync("reg", ["add", regKey, "/ve", "/t", "REG_SZ", "/d", manifestPath, "/f"]);
            } catch {
                // Browser registry entry optional if browser not installed
            }
        }
    }

    return {
        success: true,
        manifestPath
    };
}

export async function unregisterNativeHost(): Promise<boolean> {
    if (process.platform === "win32") {
        const browserKeys = [
            `HKCU\\Software\\Google\\Chrome\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\BraveSoftware\\Brave-Browser\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\BraveSoftware\\Brave-Browser-Beta\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\BraveSoftware\\Brave-Browser-Nightly\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\Microsoft\\Edge\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\Chromium\\NativeMessagingHosts\\${HOST_NAME}`,
            `HKCU\\Software\\Vivaldi\\NativeMessagingHosts\\${HOST_NAME}`
        ];

        for (const regKey of browserKeys) {
            try {
                await execFileAsync("reg", ["delete", regKey, "/f"]);
            } catch {
                // Ignore missing keys
            }
        }
        return true;
    }
    return true;
}
